// `pub use channels::*` re-exports every generated `register_<chan>`/
// `dispatch_<chan>`/`<Chan>Fn` so `relic_effects::<name>` keeps resolving.
pub use channels::*;

/// sls2：Belt Buckle 的撤销（C# `BeltBuckle.AfterPotionProcured`：战斗中有了药水且已加过敏捷，就扣回 2 点）。
/// 内核没有“获得药水”通道（加药水的地方很多），这里在每次动作 / 选牌结算完后补一次：已加过（counter == 1）
/// 且药水栏非空时扣回并清标记。对拍随机牌组 #50：Alchemize 生成药水后 C# 去掉了敏捷。
pub fn belt_buckle_reconcile(state: &mut crate::CombatState) {
    if state.player.potions.is_empty() || state.is_over {
        return;
    }
    let Some(idx) = state
        .relics
        .iter()
        .position(|r| !r.is_melted && r.kind == crate::RelicKind::BeltBuckle && r.counter == 1)
    else {
        return;
    };
    state.relics[idx].counter = 0;
    if let Some(uid) = state.player.creature_uid {
        // C# `PowerCmd.Apply<DexterityPower>(-2)`（敏捷可为负）
        crate::card_effects::apply_signed_attr_power(state, uid, crate::PowerKind::Dexterity, -2);
    }
}

/// sls2：C# `Hook.AfterPlayerTurnStart` 先让所有监听者跑 `AfterPlayerTurnStart`，再跑 `AfterPlayerTurnStartLate`
/// （Hook.cs:894-913）；Late 只有 Blood Vial 与 Fake Blood Vial（第 1 回合回血）。按装备顺序。
pub fn dispatch_after_player_turn_start_late(state: &mut crate::CombatState) {
    let kinds: smallvec::SmallVec<[crate::RelicKind; 4]> = state
        .relics
        .iter()
        .filter(|r| !r.is_melted && matches!(r.kind, crate::RelicKind::BloodVial | crate::RelicKind::FakeBloodVial))
        .map(|r| r.kind)
        .collect();
    for k in kinds {
        let _ = if k == crate::RelicKind::BloodVial {
            blood_vial::on_after_side_turn_start_blood_vial(state, crate::Side::Player)
        } else {
            fake_blood_vial::on_after_side_turn_start_fake_blood_vial(state, crate::Side::Player)
        };
    }
}

